import java.io.IOException;
import java.io.InputStreamReader;
import java.io.BufferedReader;

public class Main{

    public static void main(String[] args) throws IOException{
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));

        String[] endTime = br.readLine().split(" ");
        int totTime = Integer.valueOf(endTime[0]);
        int count_array = Integer.parseInt(endTime[1]);

        System.out.println(gcd(totTime,count_array));

    }

    private static int gcd(int totTime , int count_array){
        int result = 1;

        if(count_array > totTime){
            int tmp = count_array;
            count_array = totTime;
            totTime = tmp;
        }

        if((totTime % count_array) == 0) return count_array;
        else return gcd(count_array , totTime%count_array);

    }
}

