        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] line = br.readLine().split(" ");
        int expendedTime = Integer.parseInt(line[0]);
        int InputList = Integer.parseInt(line[1]);

        do{
            if(expendedTime > InputList){
                int tmp = expendedTime;
                expendedTime = InputList;
                InputList = tmp % InputList;
            }else if(expendedTime < InputList){
                int tmp = InputList;
                InputList = expendedTime;
                expendedTime = tmp;
            }else{
                break;
            }
        }while(expendedTime % InputList != 0);

        System.out.println(InputList);
    }
}

