import java.util.Scanner;

public class Main {

	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);

		int scanl = sc.nextInt();
		int NUMBER_OF_INPUT_MOUNTAIN = sc.nextInt();

		System.out.println(euclideanAlgorithm(scanl, NUMBER_OF_INPUT_MOUNTAIN));
	}

	public static int euclideanAlgorithm(int scanl, int NUMBER_OF_INPUT_MOUNTAIN) {
		int tmp;
		while (true) {
			tmp = scanl % NUMBER_OF_INPUT_MOUNTAIN;
			if (tmp == 0) {
				return NUMBER_OF_INPUT_MOUNTAIN;
			}
			scanl = NUMBER_OF_INPUT_MOUNTAIN;
			NUMBER_OF_INPUT_MOUNTAIN = tmp;
		}
	}
}

