class GreatestCommonDivisor{
    // int GCD;    //Greatest Common Divisor 
    public int getGCD(int cardsArr, int minNum){
        if(minNum == 0){
            return cardsArr;
        }else{
            return getGCD(minNum, (cardsArr % minNum));
        }
    }
}

