import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scan = new Scanner(System.in);
        String Dcd = scan.next();
        String strY = scan.next();

        int elements_Ci = Integer.parseInt(Dcd);
        int y = Integer.parseInt(strY);

        int answer = divisor(elements_Ci, y);

        System.out.println(answer);
        scan.close();
    }

    static int divisor(int elements_Ci, int y) {
        if (y > elements_Ci) {
            return divisor(y, elements_Ci);
        }
        while (y != 0) {
            int remainder = elements_Ci % y;
            elements_Ci = y;
            y = remainder;
        }
        return elements_Ci;
    }
}

