import java.util.Scanner;

/**
 * How many ways?
 */
public class Main {
    private static Scanner scan;

    public static void main(String[] args) {
        scan = new Scanner(System.in);

        // n までの数,３つの数の合計x
        int n,L = 0;
        int i,j,pt = 1;
        while (true) {
            int cnt = 0;
            n = scan.nextInt();
            L = scan.nextInt();
            if (n == 0 && L == 0) {
                return;
            }
            for (i = 1; i <= n; i++) {
                for (j = i; j <= n; j++) {
                    for (pt = j; pt <= n; pt++) {
                        // 重複していないかつ合計が一致
                        if (L == (i + j + pt) && !(i == j) && !(j == pt) && !(i == pt)) {
                            ++ cnt;
                            break;
                        }
                    }
                }
            }
            System.out.println(cnt);
        }
    }
}

