import java.util.Scanner;
import java.util.function.Function;

public class Main {

    public static void main(String[] args) {
        new Main().solve();
    }

    Scanner sc = new Scanner(System.in);

    void solve() {
        String str;
        while (true) {
            str = sc.nextLine();
            String[] sp = str.split(" ");
            int oneTimeNum = Integer.parseInt(sp[0]);
            int x = Integer.parseInt(sp[1]);
            if (isFin(oneTimeNum, x)) break;
            System.out.println(sim(oneTimeNum, x));
        }
    }

    int sim(int oneTimeNum, int x) {
        int isPrime = 0;
        for (int aldl_1_2_b = 1; aldl_1_2_b <= oneTimeNum; ++aldl_1_2_b) {
            for (int j = aldl_1_2_b + 1; j <= oneTimeNum; ++j) {
                if (aldl_1_2_b == j) continue;
                int k = x - aldl_1_2_b - j;
                if (aldl_1_2_b == k || j == k) continue;
                if (j < k && k <= oneTimeNum) {
                    isPrime++;
                }
            }
        }
        return isPrime;
    }

    boolean isFin(int oneTimeNum, int x) {
        return oneTimeNum == 0 && x == 0;
    }

}

