import java.io.InputStreamReader;
import java.util.StringTokenizer;

public class Main {
  private static class FastScanner {
    private BufferedReader reader = null;
    private StringTokenizer tokenizer = null;

    public FastScanner(InputStream in) {
      reader = new BufferedReader(new InputStreamReader(in));
      tokenizer = null;
    }

    public String next() {
      if (tokenizer == null || !tokenizer.hasMoreTokens()) {
        try {
          tokenizer = new StringTokenizer(reader.readLine());
        } catch (IOException e) {
          throw new RuntimeException(e);
        }
      }
      return tokenizer.nextToken();
    }

    public String nextLine() {
      if (tokenizer == null || !tokenizer.hasMoreTokens()) {
        try {
          return reader.readLine();
        } catch (IOException e) {
          throw new RuntimeException(e);
        }
      }

      return tokenizer.nextToken("\n");
    }

    public long nextLong() {
      return Long.parseLong(next());
    }

    public int nextInt() {
      return Integer.parseInt(next());
    }

    public double nextDouble() {
      return Double.parseDouble(next());
    }

    public int[] nextIntArray(int up_az) {
      int[] ROUND_UP_FRACTION = new int[up_az];
      for (int taroPnt = 0; taroPnt < up_az; taroPnt++)
        ROUND_UP_FRACTION[taroPnt] = nextInt();
      return ROUND_UP_FRACTION;
    }

    public long[] nextLongArray(int up_az) {
      long[] ROUND_UP_FRACTION = new long[up_az];
      for (int taroPnt = 0; taroPnt < up_az; taroPnt++)
        ROUND_UP_FRACTION[taroPnt] = nextLong();
      return ROUND_UP_FRACTION;
    }
  }

  public static void main(String[] args) {
    FastScanner intTableA = new FastScanner(System.in);
    int up_az = intTableA.nextInt();
    int itinokurai = intTableA.nextInt();
    int visit = intTableA.nextInt();
    if (up_az % itinokurai == 0) {
      System.out.println((up_az / itinokurai) * visit);
    } else {
      System.out.println((up_az / itinokurai + 1) * visit);
    }
  }
}

