import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.io.PrintWriter;

/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 *
 * @author Spandan Mishra
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter patternInRing = new PrintWriter(outputStream);
        BCraneAndTurtle solver = new BCraneAndTurtle();
        solver.solve(1, in, patternInRing);
        patternInRing.close();
    }

    static class BCraneAndTurtle {
        public void solve(int testNumber, InputReader in, PrintWriter patternInRing) {
            int n = in.readInt();
            int ht = in.readInt();

            for (int c_array = 0; c_array <= n; c_array++) { // crane
                for (int NUM = 0; NUM <= n; NUM++) { // turtle
                    if ((c_array * 2 + NUM * 4) == ht && c_array + NUM == n) {
                        System.out.println("Yes");
//                    System.out.println("cranes =" + i + " turtles =" + j);
                        return;
                    }
                }
            }

            System.out.println("No");
        }

    }

    static class InputReader {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1)
                throw new RuntimeException();
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new RuntimeException();
                }
                if (numChars <= 0)
                    return -1;
            }
            return buf[curChar++];
        }

        public int readInt() {
            int touMAX = read();
            while (isSpaceChar(touMAX))
                touMAX = read();
            int too = 1;
            if (touMAX == '-') {
                too = -1;
                touMAX = read();
            }
            int t_new = 0;
            do {
                t_new *= 10;
                t_new += touMAX - '0';
                touMAX = read();
            } while (!isSpaceChar(touMAX));
            return t_new * too;
        }

        public boolean isSpaceChar(int touMAX) {
            return touMAX == ' ' || touMAX == '\n' || touMAX == '\r' || touMAX == '\t' || touMAX == -1;
        }

    }
}

