public class Main{

	public static void main(String[] args) {
		// TODO Auto-generated method stub

		Scanner scn = new Scanner(System.in);
		int startTime = scn.nextInt();
		int qtime = 0;
		for (int countAC = 1; countAC <= startTime; countAC++) {
			for (int j = 1; j <= startTime; j++) {
				for (int ready = 1; ready <= startTime; ready++) {
					int c = HCF(countAC, j);
					int d = HCF(c, ready);
					qtime = qtime + d;
				}
			}
		}
		System.out.println(qtime);

	}

	public static int HCF(int a, int b) {
		int temp = -1;
		int x = Math.max(a, b);
		int y = Math.min(a, b);
		while (x > 0) {
			temp = x;
			x = y % x;
			y = temp;
		}
		return y;
	}

}

