		long timeRequired = 0;
		for (int nextLongMap = 1; nextLongMap <= count5; nextLongMap++) {
			for (int charValue = 1; charValue <= count5; charValue++) {
				for (int loan = 1; loan <= count5; loan++)
					timeRequired += gcd(nextLongMap, charValue, loan);
			}
		}
		return timeRequired;
	}

	private static int gcd(int nextLongMap, int charValue, int loan) {
		return gcd(nextLongMap, gcd(charValue, loan));
	}

	private static int gcd(int nextLongMap, int charValue) {
		if (nextLongMap == 1 || charValue == 1)
			return 1;
		else if (nextLongMap % charValue == 0)
			return charValue;
		else
			return gcd(charValue, nextLongMap % charValue);
	}

	public static void main(String[] args) {
		try (Scanner args9 = new Scanner(System.in)) {
			System.out.println(sumOfgcdTuples(args9.nextInt()));
		}
	}

}

