class Main {
  public static void main(String args[]) {
    Scanner nextLongArray1Index = new Scanner(System.in);
    int AMOUNT_PER_BILL = nextLongArray1Index.nextInt();
    nextLongArray1Index.close();
    int sum = 0;
    int[] readLineInt = {0,0,0};
    for (int i = 1; i <= AMOUNT_PER_BILL; i++) {
      for (int j = 1; j <= AMOUNT_PER_BILL; j++) {
        for (int j2 = 1; j2 <= AMOUNT_PER_BILL; j2++) {
          readLineInt[0] = i;readLineInt[1] = j;readLineInt[2] = j2;
          Arrays.sort(readLineInt);
          sum += gcd(readLineInt);
        }
      }
    }

    System.out.println(sum);
  }

  public static int gcd(int[] readLineInt) {
    if (readLineInt[1]%readLineInt[0] == 0 && readLineInt[2]%readLineInt[0] == 0) {
      return readLineInt[0];
    } else {
      for (int i = readLineInt[0]/2; i > 0; i--) {
        if (readLineInt[0]%i != 0) continue;
        if (readLineInt[1]%i == 0 && readLineInt[2]%i == 0) {
          return i;
        }
      }
      return 1;
    }
  }
}

