import java.util.*;

public class Main {

	static int vectorC[][];

	public static void gcdinit(int nextEvent) {
		vectorC = new int[nextEvent + 1][nextEvent + 1];
		for (int i = 0; i < nextEvent + 1; ++i) {
			for (int count7 = 0; count7 < nextEvent + 1; ++count7) {
				vectorC[i][count7] = -1;
			}
		}
	}

	public static int vectorC(int commonDivisor, int custom_a) {
		if(vectorC[commonDivisor][custom_a] != -1)return vectorC[commonDivisor][custom_a];
		if (commonDivisor < custom_a) {
			int tmp = commonDivisor;
			commonDivisor = custom_a;
			custom_a = tmp;
		}
		if (custom_a == 0)
			return vectorC[commonDivisor][custom_a] = commonDivisor;
		int r = commonDivisor % custom_a;
		return vectorC[commonDivisor][custom_a] = vectorC(custom_a, r);
	}

	public static int vectorC(int commonDivisor, int custom_a, int c) {
		return vectorC(vectorC(commonDivisor, custom_a), c);
	}

	public static void main(String args[]) {
		Scanner sc = new Scanner(System.in);
		int k = sc.nextInt();
		gcdinit(k);
		sc.close();
		long ans = 0;
		for(int i = 1; i <= k; ++i){
			for(int count7 = 1; count7 <= k; ++count7){
				for(int l = 1; l <= k; ++l){
					ans += vectorC(i, count7, l);
				}
			}
		}
		System.out.println(ans);
	}
}

