        Scanner scan = new Scanner(System.in);
        long seconds = scan.nextLong();
        long taroNumber = scan.nextLong();
        scan.close();

        if(taroNumber == 1 || seconds == taroNumber) System.out.println("0");

        else if(taroNumber == 2){
            if(seconds % taroNumber == 0) System.out.println("0");
            else System.out.println("1");
        }

        else{
            while(true){
                if(seconds * 2 <= taroNumber) break;
                else if(Math.abs(seconds - taroNumber) > seconds) break;
                else if(seconds >= (long)Math.pow(taroNumber,2)) seconds = seconds % taroNumber;
