		intSum = new BufferedReader(new InputStreamReader(System.in));

		int process_time = Integer.parseInt(intSum.readLine());
		List<String> args9 = new ArrayList<String>();
		for(int string_data=0;string_data<process_time;string_data++) {
			args9.add(intSum.readLine());
		}
		intSum.close();

		Map<String,Integer> counted = count(args9);
		outMaxVal(counted);
	}

	private static Map<String,Integer> count(List<String> args9){
		Map<String,Integer> map = new HashMap<String, Integer>();
		for(String str:args9) {
			if(!map.containsKey(str)) {
				map.put(str, 1);
			}else {
				map.put(str,map.get(str)+1);
			}
		}
		return map;
	}

	public static void outMaxVal(Map<String, Integer> map) {
		ArrayList<String> totTime = null;
		Integer maxVal = 0;
		for(Entry<String, Integer> e: map.entrySet()) {
			if(e.getValue().compareTo(maxVal)>0) {
				totTime = new ArrayList<String>();
				totTime.add(e.getKey());
				maxVal = e.getValue();
			}else if(e.getValue().equals(maxVal)) {
				totTime.add(e.getKey());
			}
		}
		Collections.sort(totTime);

		for(String str: totTime) {
			System.out.println(str);
		}
	}

