public class Main {

	public static void main(String[] args) {
		Scanner chn = new Scanner(System.in);
		int bigD = chn.nextInt(); //参加者
		int art = chn.nextInt(); //ポイント
		int wanted = chn.nextInt(); //クイズの回数
		int cnt_n[] =  new int[wanted]; //正解者
		for(int tlength=0;tlength<wanted;tlength++) {
			cnt_n[tlength] = chn.nextInt();
		}

		int charTemp[] = new int[bigD];
		//初期化
		for (int str02 :charTemp ) {
			str02=0;
		}

		//自分以外に、K回正解されるとアウト。
		//したがって正解数Q回ならば、自分の正解数をAとすると、Q-A<Kならいい。つまり、A＞Q-Kなら良い。
		//開始０ポイントで、正解した人は１ポイントとし、
		//終了までにQ-Kポイントよりも獲得（Q-Kはだめ）すると突破に読み換える。
		for(int tlength=0;tlength<wanted;tlength++) {
			charTemp[cnt_n[tlength]-1]++;
		}

		StringBuilder readStr = new StringBuilder();
		for (int str02 :charTemp ) {
			if(str02>wanted-art) {
				readStr.append("Yes");
				readStr.append(System.getProperty("line.separator"));
