public class Main {

//全員、「初期ポイント-問題数」してから、正解した人に「+1」する！

	public static void main(String[] args) {
		Scanner kashi = new Scanner(System.in);
		int participants = kashi.nextInt();
		int intDeque = kashi.nextInt();
		int include3 = kashi.nextInt();

		//正解した人の番号を入力
		int winner[] = new int[include3];
		for(int i=0 ; i<winner.length ; i++) {
			winner[i] = kashi.nextInt();
		}

		//全員の初期ポイントを「ポイント－問題数」にする
		int result[] = new int[participants];
		Arrays.fill(result, intDeque-include3);

		//正解した人にだけ「+1ポイント」する
		for(int i=0 ; i<include3 ; i++) {
			result[winner[i]-1]++;
		}

		//result[]の値が0より大きいか判断
		for(int i : result) {
			System.out.println(i>0 ? "Yes" : "No");
		}
		kashi.close();
	}
}

