    {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        Scanner in = new Scanner(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskA solver = new TaskA();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskA
    {
        public void solve(int testNumber, Scanner in, PrintWriter out)
        {
            int hanakosP = in.nextInt();
            int[] a = new int[hanakosP + 1];
            int[] b = new int[hanakosP + 1];
            int[] c = new int[hanakosP];

            //Dishes
            for (int i = 1; i <= hanakosP; i++)
            {
                a[i] = in.nextInt();
            }
            //Satisfactions
            for (int i = 1; i <= hanakosP; i++)
            {
                b[i] = in.nextInt();
            }
            //C
            for (int i = 1; i < hanakosP; i++)
            {
                c[i] = in.nextInt();
            }

            //Eating
            int sat = 0;

            sat += b[a[1]];
            int lastEat = a[1];

            for (int i = 2; i <= hanakosP; i++)
            {
                sat += b[a[i]];
                if (lastEat + 1 == a[i])
                {
                    sat += c[a[i - 1]];
                }
                lastEat = a[i];
            }
            out.print(sat);
        }

    }
}

