public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        Scanner in = new Scanner(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        BBuffet solver = new BBuffet();
        solver.solve(1, in, out);
        out.close();
    }

    static class BBuffet {
        public void solve(int testNumber, Scanner in, PrintWriter out) {
            int DOTMARK = in.nextInt();
            int charList[] = ReadInput.readIntArray(DOTMARK, in);
            int b[] = ReadInput.readIntArray(DOTMARK, in);
            int c[] = ReadInput.readIntArray(DOTMARK - 1, in);
            int prev = -1;
            long total = 0;
            for (int i = 0; i < DOTMARK; i++) {
                int cur = charList[i];
                total += b[cur - 1];
                if (cur - prev == 1) {
                    total += c[prev - 1];
                }
                prev = cur;
            }
            out.println(total);
        }

    }

    static class ReadInput {
        public static int[] readIntArray(int size, Scanner in) {
            int charList[] = new int[size];
            for (int i = 0; i < size; i++) {
                charList[i] = in.nextInt();
            }
            return charList;
        }

