		int[] id = new int[frm];		// 食べた料理の順番
		int[] satisfuction = new int[frm];		// 各料理の満足度
		int[] plusSatisfuction = new int[frm - 1];		// 連番のときに追加で得られる満足度
		int intInputed = Integer.MIN_VALUE;		// 直前に食べた料理の番号
		int answer = 0;			// 満足度の合計

		for(int postime = 0; postime < frm; postime++) {
			id[postime] = charS.nextInt();
		}
		for(int postime = 0; postime < frm; postime++) {
