		}

		for(int postime = 0; postime < frm; postime++) {
			answer += satisfuction[id[postime]-1];
			if(id[postime] - 1 == intInputed) {
				answer += plusSatisfuction[id[postime] - 2];
			}
			intInputed = id[postime];
		}

