import java.util.Scanner;

class Solver {
    void solve(Scanner sc) {
        int inputRowAndCol = sc.nextInt();
        int[] matrix_b = new int[inputRowAndCol];
        int[] B = new int[inputRowAndCol];
        int[] C = new int[inputRowAndCol - 1];
        for (int i = 0; i < matrix_b.length; i++) {
            matrix_b[i] = sc.nextInt() - 1;
        }
        for (int i = 0; i < B.length; i++) {
            B[i] = sc.nextInt();
        }
        for (int i = 0; i < C.length; i++) {
            C[i] = sc.nextInt();
        }
        int sum = B[matrix_b[0]];
        for (int i = 1; i < inputRowAndCol; i++) {
            int prev = matrix_b[i - 1];
            int next = matrix_b[i];
            if (prev + 1 == next) sum += C[prev];
            sum += B[next];
        }
        System.out.println(sum);
    }
}

class Main {
    public static void main(String... args) {
        Scanner in = new Scanner(System.in);

        new Solver().solve(in);

        in.close();
    }
}

