public class Main
{
  public static void main(String[] args) throws IOException
  {
     BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
     StringTokenizer tokenizer1 = new StringTokenizer(br.readLine());
     int arg1 = Integer.parseInt(tokenizer1.nextToken());
     int primeNum = Integer.parseInt(tokenizer1.nextToken());
     int ans = maximum(arg1,primeNum);
     System.out.println(ans);
  }
  public static int maximum(int arg1,int primeNum)
  {
    int getTime = arg1 + primeNum;
    int y = arg1 - primeNum;
    int z = arg1 * primeNum;

    int ans1 = Math.max(getTime,y);
    int ans = Math.max(ans1,z);
    return ans;
  }
}

