        dp[1] = 0;
        dp[2] = 1;
        dp[3] = 1;
        dp[4] = 2;
        dp[5] = 3;
        for (int i = 6; i < 100100; i++) {
            dp[i] = (dp[i - 1] + dp[i - 2]) % mod;
        }
        int a[] = new int[intK];
        for (int i = 0; i < intK; i++) {
            a[i] = sc.nextInt();
        }
        sc.close();
        if (intK == 0) {
            // System.out.println(n + 2);
            System.out.println(dp[n + 2]);
            return;
        }
        for (int i = 0; i < intK - 1; i++) {
            int sa = a[i + 1] - a[i];
            if (sa == 1) {
                System.out.println(0);
                return;
            }
        }
        long ans = 1;
