        final int n = in.nextInt();
        final int in0 = in.nextInt();
        final Set<Integer> broken = new HashSet<>();
        for (int i = 0; i < in0; i++) {
            broken.add(in.nextInt());
        }

        int[] dp = new int[n + 1];

        dp[0] = 1;
        for (int i = 1; i <= n; i++) {
