public class Main {
	static long bigInteger4=1000000007L;
	public static void main(String[] args) {
		SC sc = new SC(System.in);
		int N=sc.nextInt();
		int prec=sc.nextInt();
		long[] dp=new long[N+1];
		Arrays.fill(dp,0);
		dp[0]=1;
		int[] dan=new int[prec];
		for(int row_cout=0; row_cout<prec; row_cout++) {
			dan[row_cout]=sc.nextInt();
		}
		for(int row_cout=1; row_cout<prec; row_cout++) {
			if(dan[row_cout]-dan[row_cout-1]==1) {
				pl(0);
				System.exit(0);
			}
		}
		int hanakoP=0;
		for(int row_cout=1; row_cout<=N; row_cout++) {
			if(row_cout==1) {	//2段前がない
				if(hanakoP<prec && dan[hanakoP]==row_cout) {
					dp[row_cout]=0;	//踏めない
					hanakoP++;
				}
				else {
					dp[row_cout]=1;	//踏める
				}
			}
			else {
				if(hanakoP<prec && dan[hanakoP]==row_cout) {
					dp[row_cout]=0;
					hanakoP++;
				}
				else {
					dp[row_cout]=dp[row_cout-1]+dp[row_cout-2];
					dp[row_cout]%=bigInteger4;
				}
			}
		}
		pl(dp[N]);
	}
	static class SC {
		private BufferedReader reader = null;
		private StringTokenizer tokenizer = null;
		public SC(InputStream in) {
			reader = new BufferedReader(new InputStreamReader(in));
		}
		public String next() {
			if (tokenizer == null || !tokenizer.hasMoreTokens()) {
				try {
					tokenizer = new StringTokenizer(reader.readLine());
				} catch (IOException e) {
					throw new UncheckedIOException(e);
				}
			}
			return tokenizer.nextToken();
		}
		public int nextInt() {
			return Integer.parseInt(next());
		}
		public long nextLong() {
			return Long.parseLong(next());
		}
		public double nextDouble() {
			return Double.parseDouble(next());
		}
		public String nextLine() {
			try {
				return reader.readLine();
			} catch (IOException e) {
				throw new UncheckedIOException(e);
			}
		}
	}
	public static void pl(Object o) {
		System.out.println(o);
	}
	public static void pl() {
		System.out.println();
	}
	public static void p(Object o) {
		System.out.print(o);
	}
}

