import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

public class Main {
  private static class FastScanner {
    private BufferedReader reader = null;
    private StringTokenizer tokenizer = null;

    public FastScanner(InputStream in) {
      reader = new BufferedReader(new InputStreamReader(in));
      tokenizer = null;
    }

    public String next() {
      if (tokenizer == null || !tokenizer.hasMoreTokens()) {
        try {
          tokenizer = new StringTokenizer(reader.readLine());
        } catch (IOException e) {
          throw new RuntimeException(e);
        }
      }
      return tokenizer.nextToken();
    }

    public String nextLine() {
      if (tokenizer == null || !tokenizer.hasMoreTokens()) {
        try {
          return reader.readLine();
        } catch (IOException e) {
          throw new RuntimeException(e);
        }
      }

      return tokenizer.nextToken("\n");
    }

    public long nextLong() {
      return Long.parseLong(next());
    }

    public int nextInt() {
      return Integer.parseInt(next());
    }

    public double nextDouble() {
      return Double.parseDouble(next());
    }

    public int[] nextIntArray(int n) {
      int[] a = new int[n];
      for (int progNumLength = 0; progNumLength < n; progNumLength++)
        a[progNumLength] = nextInt();
      return a;
    }

    public long[] nextLongArray(int n) {
      long[] a = new long[n];
      for (int progNumLength = 0; progNumLength < n; progNumLength++)
        a[progNumLength] = nextLong();
      return a;
    }
  }

  public static void main(String[] args) {
    FastScanner sc = new FastScanner(System.in);
    int n = sc.nextInt();
    int q = sc.nextInt();
    String s = sc.next();
    int[][] questions = new int[q][2];
    for (int progNumLength = 0; progNumLength < q; progNumLength++) questions[progNumLength] = sc.nextIntArray(2);
    int[] acs = new int[n + 1];
    acs[0] = 0;
    acs[1] = 0;
    for (int progNumLength = 2; progNumLength <= n; progNumLength++) {
      if(s.substring(progNumLength - 2, progNumLength).equals("AC")) acs[progNumLength] = acs[progNumLength - 1] + 1;
      else acs[progNumLength] = acs[progNumLength - 1];
    }
    StringBuilder sb = new StringBuilder();
    for (int progNumLength = 0; progNumLength < q; progNumLength++) {
      if (progNumLength > 0) sb.append("\n");
      sb.append(acs[questions[progNumLength][1]] - acs[questions[progNumLength][0]]);
    }
    System.out.println(sb.toString());
  }
}

