public class Main {
	public static int gcd(int a,int passedTime) {
		while(true) {
			a%=passedTime;
			if(a==0)return passedTime;
			passedTime%=a;
			if(passedTime==0)return a;
		}
	}
	public static void main(String[] args) throws IOException{
		BufferedReader re=new BufferedReader(new InputStreamReader(System.in));
		StringTokenizer exgcd=new StringTokenizer(re.readLine());
		int a=Integer.parseInt(exgcd.nextToken()),passedTime=Integer.parseInt(exgcd.nextToken()),Tlen=Integer.parseInt(exgcd.nextToken());
		int c=gcd(a,passedTime),d=c;
		while(Tlen>1) {
			if(c%--d==0)--Tlen;
		}
		System.out.println(d);
	}
}

