public class Main {
    //K-th Common Divisor
    public static void main(String[] args) {
        Scanner crub = new Scanner(System.in);
        int BASE = crub.nextInt(), dequeue2 = crub.nextInt(), BON_ARR = crub.nextInt();
        System.out.println(helper(BASE, dequeue2, BON_ARR));
        crub.close();
    }

    public static int helper(int BASE, int dequeue2, int BON_ARR) {
        int minValue = 0;
        for (int longsort = Math.min(BASE, dequeue2); longsort >= 1; longsort--) {
            if (BASE % longsort == 0 && dequeue2 % longsort == 0) minValue++;
            if (minValue == BON_ARR) return longsort;
        }
        return 0;
    }
}

