public class Main {

	static class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        public FastScanner() {
            try {
                br = new BufferedReader(new InputStreamReader(System.in));
                st = new StringTokenizer(br.readLine());
            } catch (Exception e){e.printStackTrace();}
        }

        public String next() {
            if (st.hasMoreTokens()) return st.nextToken();
            try {st = new StringTokenizer(br.readLine());}
            catch (Exception e) {e.printStackTrace();}
            return st.nextToken();
        }

        public int nextInt() {return Integer.parseInt(next());}

        public long nextLong() {return Long.parseLong(next());}

        public double nextDouble() {return Double.parseDouble(next());}

        public String nextLine() {
            String line = "";
            if(st.hasMoreTokens()) line = st.nextToken();
            else try {return br.readLine();}catch(IOException e){e.printStackTrace();}
            while(st.hasMoreTokens()) line += " "+st.nextToken();
            return line;
        }
    }

	public static void main(String[] args) {
        FastScanner sc = new FastScanner();
        PrintWriter pw = new PrintWriter(System.out);

        int name_time = sc.nextInt(), t_ds = sc.nextInt(), k = sc.nextInt();
        int small = Math.min(name_time, t_ds);
        int cnt = 0;

        for(int DEFAULT_BUFFER_SIZE=small;DEFAULT_BUFFER_SIZE>=1;DEFAULT_BUFFER_SIZE--) {
            if(name_time % DEFAULT_BUFFER_SIZE == 0 && t_ds % DEFAULT_BUFFER_SIZE == 0) {
                cnt++;
            }
            if(cnt == k) {
                pw.println(DEFAULT_BUFFER_SIZE);
                break;
            }
        }

        pw.close();
    }
}

