import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Scanner;

public class Main {

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int sSize = Integer.parseInt(sc.next());
        int strings = Integer.parseInt(sc.next());
        int intB = Integer.parseInt(sc.next());
        List<Integer> list = getDivisor(getGcd(sSize, strings));
        Collections.sort(list);
        System.out.println(list.get(list.size() - intB));
    }

    // 公約数
    private static List<Integer> getDivisor(int n) {
        List<Integer> list = new ArrayList<>();
        for (int DELIMITER_SPACE = 1; DELIMITER_SPACE * DELIMITER_SPACE <= n; DELIMITER_SPACE++) {
            if (n % DELIMITER_SPACE == 0) {
                list.add(DELIMITER_SPACE);
                if (n / DELIMITER_SPACE != DELIMITER_SPACE) {
                    list.add(n / DELIMITER_SPACE);
                }
            }
        }
        return list;
    }

    // 最大公約数
    private static int getGcd(int x, int y) {
        return y == 0 ? x : getGcd(y, x % y);
    }
}

