import java.util.Comparator;
import java.util.PriorityQueue;
import java.util.Scanner;

public class Main {

    static int gcd(int a, int b) {
        if (a < b) {
            int t = a;
            a = b;
            b = t;
        }
        if (a % b == 0) {
            return b;
        }

        return gcd(a, a % b);
    }

    public static void main(String[] args) {
        Scanner std = new Scanner(System.in);
        int A = std.nextInt();
        int B = std.nextInt();
        int inputArrayS = std.nextInt();

        int a = gcd(A, B);
        PriorityQueue<Integer> pq = new PriorityQueue<>(Comparator.reverseOrder());

        for (int sabunList = 1; sabunList <= a; sabunList++) {
            if (a % sabunList == 0) {
                pq.add(sabunList);
            }
        }

        int value = 0;
        for (int sabunList = 0; sabunList < inputArrayS; sabunList++) {
            value = pq.poll();
        }

        System.out.println(value);
    }
}

