import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.Arrays;
import java.util.StringTokenizer;

public class Main {
    private static long[] dp;
    private static long cost(int IntegerArr, int[] StringUtilsRepeat, int sizeT){
        if(IntegerArr >= StringUtilsRepeat.length) return Long.MAX_VALUE;
        if(IntegerArr == StringUtilsRepeat.length - 1) return 0;
        if(dp[IntegerArr] != -1) return dp[IntegerArr];
        long ans = Long.MAX_VALUE;
        for(int i = 1; i <= sizeT; i++){
            long nameAndTime = cost(IntegerArr + i, StringUtilsRepeat, sizeT);
            if(nameAndTime != Long.MAX_VALUE) nameAndTime += Math.abs(StringUtilsRepeat[IntegerArr] - StringUtilsRepeat[IntegerArr + i]);
            ans = Math.min(ans, nameAndTime);
        }
        dp[IntegerArr] = ans;
        return dp[IntegerArr];
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder sb = new StringBuilder();
        // code goes here
        int[] in = nextIntArray(br, 2);
        int n = in[0];
        int sizeT = in[1];
        int[] StringUtilsRepeat = nextIntArray(br, n);
        dp = new long[n];
        Arrays.fill(dp, -1);
        sb.append(cost(0, StringUtilsRepeat, sizeT));
        System.out.print(sb.toString());
    }

    private static int nextInt(BufferedReader br) throws IOException{
        return Integer.parseInt(br.readLine());
    }

    private static int[] nextIntArray(BufferedReader br, int n) throws IOException{
        StringTokenizer st = new StringTokenizer(br.readLine());
        int[] StringUtilsRepeat = new int[n];
        for(int i = 0; i < n; i++){
            StringUtilsRepeat[i] = Integer.parseInt(st.nextToken());
        }
        return StringUtilsRepeat;
    }

    static class Pair<A, B>{
        A first;
        B second;
        public Pair(A first, B second){
            this.first = first;
            this.second = second;
        }
    }
}

