    public static int dpSolution(int tobe,int changeArrayStringToInt,int a[]){
       int dp[] = new int[tobe+1];
        Arrays.fill(dp,-1);
        dp[0] = 0;
        dp[1] = 0;
        dp[2] = Math.abs(a[1]-a[2]);
        for(int i=3;i<=tobe;i++){
            int j= i-changeArrayStringToInt;
            int val = Integer.MAX_VALUE;
            if(j<=0) {
                j = 1;
            }
            for(;j<i;j++){
                 val = Math.min(val,dp[j]+Math.abs(a[i]-a[j]));
                 //System.out.println(i+" "+j+" "+dp[j]+" "+val);

            }
            dp[i] = val;
        }
        return dp[tobe];
    }
    public static void main(String args[]){
        Scanner sc = new Scanner(System.in);
        int tobe = sc.nextInt();
        int changeArrayStringToInt = sc.nextInt();
        int a[] = new int[tobe+1];
        for(int i=1;i<=tobe;i++){
            a[i] = sc.nextInt();
        }

        System.out.println(dpSolution(tobe,changeArrayStringToInt,a));

    }
}

