import java.util.*;
import java.io.*;
public class Main {
    public static void main(String args[]) {

      Scanner sc = new Scanner(System.in);
      PrintWriter w = new PrintWriter(System.out);
      //Input Part
      int hitoketa = sc.nextInt();
      int a_b = sc.nextInt();
      int entry2[] = new int[hitoketa];
      for(int i = 0; i < hitoketa; i++)
      {
          entry2[i] = sc.nextInt();
      }

      //Logic Part
      int dp[] = new int[hitoketa];
      dp[0] = 0;
      dp[1] = Math.abs(entry2[1] - entry2[0]);
      for(int i = 2; i < hitoketa; i++)
      {
          dp[i] = dp[i-1] + Math.abs(entry2[i] - entry2[i-1]);
          for(int a_b = 2; a_b <= a_b; a_b++)
          {
              if(a_b <= i && a_b < hitoketa)
              {
                  dp[i] = Math.min(dp[i], dp[i-a_b] + Math.abs(entry2[i] - entry2[i-a_b]));
              }
          }
      }
      w.println(dp[hitoketa-1]);
      w.close();
    }
}

