public class Main {


    public static void main(String[] args) {
        // write your code here
        Scanner scanner = new Scanner(System.in);
        int countNumbers = scanner.nextInt();
        int num3 = scanner.nextInt();
        int heights[] = new int[countNumbers];
        for (int j = 0; j < heights.length; j++) {
            heights[j] = scanner.nextInt();
        }
        long numOfWays = getNumOfWays(heights, num3);
        System.out.println(numOfWays);
    }

    private static long getNumOfWays(int hei[], int num3) {

        long numS[] = new long[hei.length];
        for (int countNumbers = numS.length - 2; countNumbers >= 0; countNumbers--) {
            long cost = Integer.MAX_VALUE;
            int end = Math.min(numS.length - 1, countNumbers + num3);
            for (int j = countNumbers + 1; j <= end; j++) {
                cost = Math.min(Math.abs(hei[countNumbers] - hei[j]) + numS[j], cost);
            }
            numS[countNumbers] = cost;
        }
        return numS[0];
    }


}

