import java.util.*;
import java.lang.*;
import java.io.*;

class Main
{
	static Integer dp[];

	static int minimumJumps(int ar[], int i, int floor3)
	{
		if(i==0)
			return 0;

		if(dp[i]!=null)
			return dp[i];

		int min=Integer.MAX_VALUE;
		int st=Math.max(i-floor3, 0);

		for(int j=st;j<i;j++)
		{
			if(dp[j]==null)
				min = Math.min(min, minimumJumps(ar, j, floor3)+Math.abs(ar[i]-ar[j]));
			else
				min = Math.min(min, dp[j]+Math.abs(ar[i]-ar[j]));
		}
		return dp[i]=min;
	}

	public static void main(String[] args)
	{
		Scanner scan=new Scanner(System.in);
		int bigInteger3=scan.nextInt();
		int floor3=scan.nextInt();
		int ar[]=new int[bigInteger3];
		for(int i=0;i<bigInteger3;i++)
			ar[i]=scan.nextInt();

		dp=new Integer[bigInteger3];

		int ans = minimumJumps(ar, ar.length-1, floor3);
		System.out.println(ans);
	}
}

