import java.util.Scanner;

public class Main {

    public static int ans(int divisors[], int imput, int Sarray){
        int storage[] = new int[imput+1];
        storage[1] = 0;
        for(int i=2; i<=imput; i++){
           storage[i] = Integer.MAX_VALUE;

           for(int j=i-1; j>=1 && (i-j)<=Sarray; j--){
               storage[i] = Math.min(Math.abs(divisors[i] - divisors[j]) + storage[j], storage[i]);
           }

        }
        return storage[imput];
    }

    public static void main(String args[]) {
        Scanner sc = new Scanner(System.in);
        int imput = sc.nextInt();
        int Sarray = sc.nextInt();
        int divisors[] = new int[imput+1];
        for(int i=1; i<=imput; i++){
            divisors[i] = sc.nextInt();
        }
        System.out.println(ans(divisors, imput, Sarray));
    }
}

