    final long MOD = 1000L * 1000L * 1000L + 7;
    private static final int[] dx = {0, -1, 0, 1};
    private static final int[] dy = {1, 0, -1, 0};

    void solve() throws IOException {
        int n = nextInt();
        int existX = nextInt();
        int[] arr = nextIntArr(n);
        int[] count2 = new int[n];
        Arrays.fill(count2, Integer.MAX_VALUE);
        count2[0] = 0;
        for (int i = 0; i < n; i++) {
            for (int j = 1; j <= existX; j++) {
                if (i + j < n) {
                    count2[i + j] = Math.min(count2[i + j], Math.abs(arr[i + j] - arr[i]) + count2[i]);
                }
            }
        }
        outln(count2[n - 1]);
    }

    void shuffle(int[] a) {
        int n = a.length;
        for(int i = 0; i < n; i++) {
            int r = i + (int) (Math.random() * (n - i));
            int tmp = a[i];
            a[i] = a[r];
            a[r] = tmp;
        }
    }
