import java.util.Scanner;

public class Main {

	//計算に使う定数
	private static final int SubT = 10000;
	private static final int mean  = 5000;
	private static final int uhouho  = 1000;

	public static void main(String[] args) {

		// 処理対象個数の入力
		Scanner strIn = new Scanner(System.in);
		int inputBillNum = strIn.nextInt();
		int has3 = strIn.nextInt();

		// 札の枚数の組の初期値を代入
		int isPossible = -1;
		int nextfloat = -1;
		int num1k = -1;

		for(int i = 0;i <= inputBillNum;i++) {
			for(int j = 0;i + j <= inputBillNum;j++) {
				if(i * SubT + j * mean + (inputBillNum-(i+j)) * uhouho == has3) {
					isPossible = i;
					nextfloat = j;
					num1k = inputBillNum-(i+j);
					break;
				}else if(isPossible * SubT + nextfloat * mean + inputBillNum-(isPossible+nextfloat) * uhouho > has3){
					continue;
				}
			}
		}

		strIn.close();

		// 出力
		System.out.println(isPossible+" "+nextfloat+" "+num1k);

	}

}

