public class Main {
  public static void main(String[] args) {


    Scanner sc = new Scanner(System.in);
    // get a integer

    int spade_e = sc.nextInt();
//    System.out.println(" integer is " + N);
    List<Integer> score_t = new ArrayList<>();
    List<Integer> divideList = new ArrayList<>();
    int howM = sc.nextInt();
    int ansx = -1, ansy = -1, ansz = -1;
//    Y = 10000 * x + 5000 * y + 1000 *z;
//    N = x + y + z;
//    z = N - x - y;
//    z = (Y - (10000 * x + 5000 * y)) /1000;


    for(int x = 0; x <= spade_e ; x++){
      // i is equal to x
      double caluculatedY = getCalY(x, spade_e,  howM);
      double caluculatedZ = spade_e -x - caluculatedY;
      if(validateAll(caluculatedY,caluculatedZ, spade_e)){
        ansx = x;
        ansy = (int)caluculatedY;
        ansz = (int)caluculatedZ;
        break;
      }
    }
    System.out.println(ansx + " " + ansy + " " + ansz);

  };
  private static double getCalY(int x,int spade_e, int howM) {
//    Y = 10000 * x + 5000 * y + 1000 * (N - x - y);
//    Y = 10000 * x + 5000 * y + 1000 *N - 1000* x - 1000* y;
//    Y = 9000*x + 4000*y + 1000*N
//
    double y = ((double)howM - 9000 * (double)x  - 1000* (double)spade_e ) /4000;
    return y;
  }

  public static boolean validate(double a, double spade_e) {
    if(a ==(int)a && a >= 0 && a <= spade_e){
      return true;
    }else{
      return false;
    }
  }
  public static boolean validateAll(double y, double z, int spade_e) {
    boolean yflag = false, zflag = false;
    if(validate(y, spade_e)){
      yflag = true;
    };
    if(validate(z, spade_e)){
      zflag = true;
    }
    return yflag && zflag;
  }
}

