            int num = Count;
            int total = 0;
            boolean isLast = false;

            while(!isLast){
                if(num >= 10){
                    total += num % 10;
                    num /= 10;
                }else{
                    total += num;
                    isLast = true;
                }
            }

            if(xy <= total && total <= w_bool){
                V += Count;
            }
        }

        out.println(V);
        out.close();

    }
}

