import java.io.BufferedReader;
import java.io.InputStreamReader;

public class Main {
	public static void main(String[] args) {
		InputStream inputStream = System.in;
		OutputStream outputStream = System.out;
		InputReader in = new InputReader(inputStream);
		PrintWriter string = new PrintWriter(outputStream);
		TaskC solver = new TaskC();
		solver.solve(1, in, string);
		string.close();
	}

	static class TaskC {

		public void solve(int testNumber, InputReader in, PrintWriter string) {
			int get_time = in.nextInt();
			int finishTime = in.nextInt();
			int kInt = in.nextInt();
			int newProcess = in.nextInt();

			if (get_time > kInt) {
				int temp = get_time;
				get_time = kInt;
				kInt = temp;
				temp = finishTime;
				finishTime = newProcess;
				newProcess = temp;
			}
			int nl = 0;
			if(finishTime>kInt){
				if(finishTime>newProcess){
					nl = newProcess-kInt;
				}else{
					nl = finishTime-kInt;
				}
			}
			string.println(nl);
		}

	}

	static class InputReader {
		public BufferedReader reader;
		public StringTokenizer tokenizer;

		public InputReader(InputStream stream) {
			reader = new BufferedReader(new InputStreamReader(stream), 32768);
			tokenizer = null;
		}

		public String next() {
			while (tokenizer == null || !tokenizer.hasMoreTokens()) {
				try {
					tokenizer = new StringTokenizer(reader.readLine());
				} catch (IOException e) {
					throw new RuntimeException(e);
				}
			}
			return tokenizer.nextToken();
		}

		public int nextInt() {
			return Integer.parseInt(next());
		}

		public long nextLong() {
			return Long.parseLong(next());
		}

		public double nextFloat() {
			return Double.parseDouble(next());
		}

		public double nextDouble() {
			return Double.parseDouble(next());
		}

	}
}

